const WHITELIST = ['5591982250731']; // [] = responde a todos os contatos diretos
const EVOLUTION = 'http://evolution-api:8080';
const EVO_KEY = '7539443e08ab02320e9afd7d9b2149c9';
const INSTANCE = 'principal';
const CRM = 'http://sansol-crm:3000';
const WA_TOKEN = '45d0608818ca6462b540e615fc0b6f1ade82db2045b4d1dc';
const OLLAMA = 'http://host.docker.internal:11434';
const MODEL = 'llama3.1:8b';
const H_JSON = { 'Content-Type': 'application/json' };
const H_CRM = { 'Content-Type': 'application/json', 'x-webhook-token': WA_TOKEN };
const H_EVO = { 'Content-Type': 'application/json', apikey: EVO_KEY };

const http = async (o) => this.helpers.httpRequest(o);
const res = await http({ method: 'GET', url: CRM + '/api/wa/followups', headers: H_CRM });
const items = res.items || [];
const out = [];
for (const it of items) {
  const first = String(it.name || '').split(' ')[0] || 'tudo bem';
  let msg;
  try {
    const sys = 'Você é a Sol, da Sansol Energia Solar. Escreva UMA mensagem curta, calorosa e sem pressão para um cliente que parou de responder há alguns dias, retomando o papo sobre energia solar. Trate pelo primeiro nome. No máximo 2 frases. Responda só com a mensagem, sem aspas.';
    const ai = await http({ method: 'POST', url: OLLAMA + '/api/chat', headers: H_JSON, body: { model: MODEL, stream: false, options: { temperature: 0.6 }, messages: [{ role: 'system', content: sys }, { role: 'user', content: 'Cliente: ' + it.name + '. Resumo da conversa: ' + (it.history || []).map(m => (m.direction === 'in' ? 'Cliente' : 'Sansol') + ': ' + m.body).join(' | ') }] } });
    msg = String(ai.message?.content || '').trim();
  } catch (e) {
    msg = 'Oi ' + first + '! Passando pra saber se você ainda tem interesse em economizar na conta de luz com energia solar 🌞 Posso te ajudar?';
  }
  if (!msg) continue;
  const sent = await http({ method: 'POST', url: EVOLUTION + '/message/sendText/' + INSTANCE, headers: H_EVO, body: { number: it.phone, text: msg } });
  await http({ method: 'POST', url: CRM + '/api/wa/outbound', headers: H_CRM, body: { conversationId: it.conversationId, text: msg, providerMessageId: sent?.key?.id } });
  await http({ method: 'POST', url: CRM + '/api/wa/followup-sent', headers: H_CRM, body: { conversationId: it.conversationId } });
  out.push({ json: { phone: it.phone, msg } });
  await new Promise(r => setTimeout(r, 4000));
}
return out.length ? out : [{ json: { note: 'sem follow-ups pendentes' } }];
